// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Olasılık hesapları ve koşullu olasılık (zor).
const ozStatistics7Zor = <(String, String, List<String>, String)>[
  ('1\'den 100\'e kadar olan tam sayılardan biri rastgele seçiliyor. Seçilen sayının 2, 3 ya da 5\'ten en az birine bölünebilme olasılığı kaçtır?', '0,74', ['0,765', '0,77', '0,26'], 'İçerme-dışarmayla 50 + 33 + 20 − 16 − 10 − 6 + 3 = 74 sayı bulunur; olasılık 74/100\'dür.'),
  ('1\'den 60\'a kadar olan tam sayılardan biri rastgele seçiliyor. Sayının 2\'ye, 3\'e ve 5\'e bölünemeyen bir sayı olma olasılığı kaçtır?', '4/15', ['1/4', '11/30', '7/30'], '60 bu üç asalın katı olduğundan oran (1/2)(2/3)(4/5) = 4/15\'tir; 60 içinde 16 sayı bu koşulu sağlar.'),
  ('A, B ve C olaylarından tam olarak ikisinin gerçekleşme olasılığı hangi ifadeye eşittir?', 'P(A∩B) + P(A∩C) + P(B∩C) − 3P(A∩B∩C)', ['P(A∩B) + P(A∩C) + P(B∩C) − P(A∩B∩C)', 'P(A∩B) + P(A∩C) + P(B∩C) − 4P(A∩B∩C)', 'P(A∩B) + P(A∩C) + P(B∩C) − 2P(A∩B∩C)'], 'Üçlü kesişim, ikili kesişimlerin her birinde bir kez, toplamda üç kez sayılır; tam iki olay için üçü de çıkarılmalıdır.'),
  ('Bir makinedeki 10 parçanın her biri bir yıl içinde 0,02 olasılıkla arızalanıyor; parçaların birbirini etkileyip etkilemediği bilinmiyor. En az bir parçanın arızalanma olasılığı için kesin olarak söylenebilecek üst sınır kaçtır?', '0,2', ['0,02', '0,18', '0,1'], 'Boole eşitsizliğine göre birleşimin olasılığı olasılıkların toplamını aşamaz: 10 × 0,02 = 0,2. Bu sınır bağımlılıktan bağımsız olarak geçerlidir.'),
  ('Bir zar atılıyor. A = {1, 2, 3}, B = {2, 4, 6} ve C = {3, 6} olaylarından en az birinin gerçekleşmeme olasılığı, yani P(A\' ∪ B\' ∪ C\') kaçtır?', '1', ['5/6', '1/2', '2/3'], 'A ∩ B ∩ C boş kümedir, çünkü 2 C\'de, 3 B\'de, 6 A\'da yoktur. Tümleyeni kesin olay olduğundan olasılık 1\'dir.'),
  ('Olasılıkları sıfırdan büyük iki olay için P(A|B) > P(A) olduğu biliniyor. Aşağıdakilerden hangisi de kesinlikle doğrudur?', 'P(B|A) > P(B)', ['P(B|A) < P(B)', 'P(A|B) > P(B|A)', 'P(A ∩ B) < P(A)·P(B)'], 'P(A|B) > P(A) eşitsizliği P(A ∩ B) > P(A)P(B) demektir; bu da her iki yönde koşullu olasılığın artması anlamına gelir.'),
  ('İki olayın kesişiminin olasılığı 0,12\'dir. Ayrıca P(A|B) = 0,3 ve P(B|A) = 0,4 olduğu biliniyor. Bu bilgilere göre olaylardan en az birinin gerçekleşme olasılığı kaçtır?', '0,58', ['0,625', '0,46', '0,82'], 'P(B) = 0,12/0,3 = 0,4 ve P(A) = 0,12/0,4 = 0,3\'tür. P(A ∪ B) = 0,3 + 0,4 − 0,12 = 0,58 olur.'),
  ('Bir kutudaki 6 ampulden 2\'si bozuktur. Ampuller rastgele sırayla tek tek denenip bozuklar bulunuyor. İkinci bozuk ampulün tam olarak üçüncü denemede bulunma olasılığı kaçtır?', '2/15', ['1/15', '4/45', '4/15'], 'Bozukların sıradaki yerleri C(6, 2) = 15 eşit olası biçimde seçilir. İkinci bozuğun 3. sırada olması için ilki 1. ya da 2. sırada olmalıdır: 2/15.'),
  ('Bir öğrenci P(A|B) = 0,8 ve P(B) = 0,5 olduğunu biliyor ve P(A) için kesin bir şey söylemek istiyor. Hangisi kesinlikle doğrudur?', 'P(A) ≥ 0,4', ['P(A) = 0,8', 'P(A) = 0,4 ve P(A|B\') = 0', 'P(A) ≤ 0,5'], 'P(A ∩ B) = 0,8 × 0,5 = 0,4\'tür. A, A ∩ B\'yi kapsadığından P(A) en az 0,4\'tür; kesin değeri için P(A|B\') gerekir.'),
  ('Bir A olayının kendisinden bağımsız olması, yani P(A ∩ A) = P(A)·P(A) eşitliğinin sağlanması hangi durumda mümkündür?', 'Yalnız P(A) 0 ya da 1 ise', ['Yalnız P(A) = 1/2 ise', 'Her olay için', 'Hiçbir olay için; tanım iki ayrı olay gerektirir'], 'P(A) = P(A)² eşitliği yalnız P(A) = 0 ya da P(A) = 1 için sağlanır.'),
  ('İki zar atılıyor. A = "birinci zar çift", B = "toplam 8" olayları için hangisi doğrudur?', 'Bağımlıdırlar; P(A ∩ B) = 1/12 olup çarpımdan farklıdır', ['Bağımsızdırlar; P(A ∩ B) = 5/72\'dir', 'Ayrıktırlar; birlikte gerçekleşemezler', 'Bağımsızdırlar; birinci zarın değeri toplamı hiçbir biçimde etkilemez'], 'A ∩ B = {(2,6), (4,4), (6,2)} olup olasılığı 3/36 = 1/12\'dir. P(A)P(B) = (1/2)(5/36) = 5/72 ile eşit olmadığından bağımlıdırlar.'),
  ('İki jokerden birinin çıkarıldığı 53 kartlık bir desteden, yani 52 standart karta bir joker eklenmiş desteden bir kart çekiliyor. "As çekme" ve "maça çekme" olayları için hangisi doğrudur?', 'Bağımlıdırlar, çünkü joker iki olaya da girmez', ['Bağımsızdırlar, çünkü 52\'lik destede bağımsızdırlar', 'Ayrıktırlar', 'Bağımsızdırlar, çünkü maça ası tektir'], 'P(as) = 4/53, P(maça) = 13/53, P(maça ası) = 1/53\'tür. (4/53)(13/53) = 52/2809 ile 1/53 = 53/2809 eşit değildir.'),
  ('Dört olayın karşılıklı (tam) bağımsız sayılması için kaç ayrı çarpım eşitliğinin sağlanması gerekir?', '11', ['4', '14', '15'], 'İkili 6, üçlü 4 ve dörtlü 1 kesişim için eşitlik gerekir: 6 + 4 + 1 = 11, yani 2⁴ − 4 − 1.'),
  ('Üç olay için yalnızca P(A ∩ B ∩ C) = P(A)·P(B)·P(C) eşitliğinin sağlandığı biliniyor. Bu bilgi için hangisi doğrudur?', 'Karşılıklı bağımsızlık için yeterli değildir', ['Üç olayın karşılıklı bağımsız olduğunu kanıtlar', 'İkili bağımsızlığı kanıtlar ama üçlüyü kanıtlamaz', 'Olayların ayrık olduğunu gösterir'], 'Karşılıklı bağımsızlık için ikili kesişimlerin de çarpıma eşit olması gerekir; üçlü eşitlik tek başına bunu sağlamaz.'),
  ('Bağımsız A ve B olayları için P(A ∩ B) = 0,2 ve P(A ∪ B) = 0,7\'dir. P(A) > P(B) olduğuna göre P(A) kaçtır?', '0,5', ['0,4', '0,6', '0,45'], 'P(A) + P(B) = 0,9 ve P(A)P(B) = 0,2 olur. x² − 0,9x + 0,2 = 0 denkleminin kökleri 0,5 ve 0,4\'tür.'),
  ('Bir kutuda bir hilesiz para ve iki yüzü de yazı olan bir para vardır. Rastgele seçilen para iki kez atılıyor. Paranın türü bilinmediğinde iki atışın bağımlı olmasının nedeni nedir?', 'İlk atış hangi paranın seçildiğine dair bilgi verir', ['Para atışları her zaman bağımlıdır', 'İkinci atış, ilk atışın paranın üzerinde bıraktığı fiziksel etkiyi taşır', 'Hileli para iki kez atılamaz'], 'Para bilindiğinde atışlar bağımsızdır; bilinmediğinde ilk yazı, hileli paranın seçilmiş olma olasılığını artırır ve ikinci atışın olasılığını değiştirir.'),
  ('Bir kutuda bir hilesiz para ve iki yüzü de yazı olan bir para vardır. Rastgele seçilen bir para atılıyor ve yazı geliyor. Aynı para yeniden atılırsa yazı gelme olasılığı kaçtır?', '5/6', ['11/12', '1/2', '2/3'], 'P(iki yazı) = (1/2)(1/4) + (1/2)(1) = 5/8, P(ilk yazı) = 3/4\'tür. Koşullu olasılık (5/8)/(3/4) = 5/6 olur.'),
  ('Bir hastalığa sahip kişilerde iki farklı testin sonuçları birbirinden bağımsızdır; sağlıklı kişilerde de öyledir. Hastalık bilinmeden bakıldığında iki test sonucu için genellikle ne beklenir?', 'Pozitif yönde ilişkili olurlar', ['Bağımsız olurlar', 'Negatif yönde ilişkili ya da tümüyle ayrık olurlar', 'Her zaman aynı sonucu verirler'], 'Bir testin pozitif çıkması kişinin hasta olma olasılığını artırır; bu da diğer testin pozitif çıkma olasılığını yükseltir. Koşullu bağımsızlık koşulsuz bağımsızlık anlamına gelmez.'),
  ('Yaygınlığı %1 olan bir hastalık için testin duyarlılığı %90, yanlış pozitif oranı %5\'tir. Bir kişinin testi pozitif çıkıyor; aynı test, sonuçları kişinin durumu bilindiğinde bağımsız olacak biçimde yeniden uygulanıyor ve yine pozitif çıkıyor. Kişinin hasta olma olasılığı yaklaşık kaçtır?', '0,77', ['0,15', '0,90', '0,9775'], 'İlk pozitiften sonra olasılık ≈ 0,154 olur ve bu yeni önsel kabul edilir. 0,154 × 0,9 / (0,154 × 0,9 + 0,846 × 0,05) ≈ 0,77 bulunur.'),
  ('Bir hastalığın yaygınlığı %2\'dir. Pozitif olabilirlik oranı 10 olan bir testte sonucu pozitif çıkan kişinin hasta olma olasılığı yaklaşık kaçtır?', '0,17', ['0,20', '0,02', '0,833'], 'Önsel oran 2/98\'dir. 10 ile çarpılınca 20/98 olur; olasılığa çevirince 20/118 ≈ 0,17 bulunur.'),
  ('Bir kentte taksilerin %85\'i yeşil, %15\'i mavidir. Bir gece kazasında tanık taksinin mavi olduğunu söylüyor; tanığın renkleri doğru tanıma olasılığı %80\'dir. Taksinin gerçekten mavi olma olasılığı yaklaşık kaçtır?', '0,41', ['0,80', '0,15', '0,585'], 'P(mavi dedi) = 0,15 × 0,8 + 0,85 × 0,2 = 0,29\'dur. P(mavi | mavi dedi) = 0,12 / 0,29 ≈ 0,41 bulunur.'),
  ('Bir evde bir gece hırsızlık olma olasılığı 0,001\'dir. Alarm hırsızlıkta 0,99 olasılıkla çalıyor, hırsızlık yokken 0,01 olasılıkla boşuna çalıyor. Alarm çaldığında hırsızlık olma olasılığı yaklaşık kaçtır?', '0,09', ['0,99', '0,50', '0,0099'], 'P(hırsızlık ∩ alarm) = 0,00099; P(alarm) = 0,00099 + 0,00999 = 0,01098\'dir. Oran yaklaşık 0,09\'dur; boşuna alarmlar çok daha sık olduğu için sonsal düşük kalır.'),
  ('Bir hastalığın yaygınlığı %20, testin duyarlılığı %80, özgüllüğü %90\'dır. Testi negatif çıkan bir kişinin yine de hasta olma olasılığı yaklaşık kaçtır?', '0,053', ['0,20', '0,04', '0,1053'], 'P(negatif ∩ hasta) = 0,2 × 0,2 = 0,04; P(negatif ∩ sağlıklı) = 0,8 × 0,9 = 0,72\'dir. 0,04 / 0,76 ≈ 0,053 bulunur.'),
  ('Birinci torbada 3 kırmızı 1 beyaz, ikinci torbada 1 kırmızı 3 beyaz top vardır. Torbalardan biri eşit olasılıkla seçilip yerine koyarak iki top çekiliyor ve ikisi de kırmızı geliyor. Birinci torbanın seçilmiş olma olasılığı kaçtır?', '0,9', ['0,75', '0,5625', '0,8'], 'Olabilirlikler (3/4)² = 9/16 ve (1/4)² = 1/16\'dır. Eşit önsellerle 9/16 ÷ 10/16 = 0,9 bulunur.'),
  ('1.000.000 nüfuslu bir kentte bir suçun failinin bu kentten tek bir kişi olduğu varsayılıyor. Olay yerindeki iz, masum bir kişiyle 1/10.000 olasılıkla rastlantısal olarak eşleşiyor. Kent nüfusu rastgele taranıp eşleşen biri bulunursa bu kişinin fail olma olasılığı yaklaşık kaçtır?', '1/101', ['9999/10000', '1/10.000', '1/2'], 'Failin yanında yaklaşık 100 masum kişi de eşleşir. Eşleşen yaklaşık 101 kişiden yalnız biri faildir; P(eşleşme | masum) ile P(masum | eşleşme) aynı şey değildir.'),
  ('Önsel olasılığı 0 olan bir hipotez için Bayes güncellemesi hakkında hangisi doğrudur?', 'Hiçbir kanıt onun sonsal olasılığını sıfırdan yukarı çıkaramaz', ['Güçlü bir kanıt sonsal olasılığı 1\'e çıkarabilir', 'Sonsal olasılık olabilirlik oranına eşit olur', 'Kanıt sayısı arttıkça sonsal olasılık giderek 1/2 değerine yaklaşır'], 'Sonsal, önsel ile olabilirliğin çarpımıyla orantılıdır; önsel sıfırsa çarpım da sıfır kalır.'),
  ('İki çocuklu bir ailede çocuklardan en az birinin salı günü doğmuş bir erkek olduğu biliniyor. Cinsiyetler eşit olası, doğum günleri haftanın günlerine eşit dağılmış ve bağımsız ise iki çocuğun da erkek olma olasılığı kaçtır?', '13/27', ['1/3', '1/2', '14/27'], 'Koşulu sağlayan 14 × 14 − 13 × 13 = 27 eşit olası durum vardır; bunların 7 + 7 − 1 = 13\'ünde iki çocuk da erkektir.'),
  ('İki çocuklu bir aileyi ziyaret eden biri, kapıyı açan çocuğun kız olduğunu görüyor; kapıyı hangi çocuğun açacağı rastgeledir. Diğer çocuğun da kız olma olasılığı kaçtır?', '1/2', ['1/3', '2/3', '5/12'], 'Rastgele görülen tek bir çocuk bilgisi, "en az biri kız" bilgisinden daha özeldir. KK ailesinde gözlem olasılığı 1, karışık ailelerde 1/2 olduğundan sonsal 1/2 çıkar.'),
  ('Monty Hall oyununun bir biçiminde sunucu ödülün yerini bilmiyor ve kalan iki kapıdan birini rastgele açıyor; açılan kapı tesadüfen boş çıkıyor. Bu durumda seçimini değiştiren yarışmacının kazanma olasılığı kaçtır?', '1/2', ['2/3', '1/3', '5/12'], 'Sunucu bilgisiz olduğunda boş kapı açılması iki kapalı kapıya eşit kanıt sağlar; koşullu olasılıklar 1/2 ve 1/2 olur.'),
  ('Dört kapılı bir Monty Hall oyununda yarışmacı bir kapı seçiyor; ödülün yerini bilen sunucu boş kapılardan birini açıyor. Yarışmacı seçimini değiştirip kalan iki kapıdan birini rastgele seçerse kazanma olasılığı kaçtır?', '3/8', ['1/4', '1/2', '3/16'], 'İlk seçim 3/4 olasılıkla yanlıştır. Bu durumda ödül kalan iki kapıdan birindedir ve rastgele seçimle 1/2 olasılıkla bulunur: (3/4)(1/2) = 3/8.'),
  ('Monty Hall oyununda yarışmacı 1. kapıyı seçiyor. Sunucu ödülün yerini biliyor; ödül 1. kapıdaysa her zaman 3. kapıyı açma alışkanlığı vardır. Sunucu 2. kapıyı açarsa seçimini değiştiren yarışmacının kazanma olasılığı kaçtır?', '1', ['2/3', '1/2', '1/3'], 'Ödül 1. kapıda olsaydı sunucu 3\'ü açardı. 2\'yi açtığına göre ödül 1\'de değildir ve 2\'de de olamaz; ödül kesinlikle 3. kapıdadır.'),
  ('A, B ve C mahkumlarından rastgele biri affedilecektir. Kimin affedileceğini bilen gardiyan, A\'nın isteği üzerine B ve C\'den idam edilecek olanlardan birinin adını veriyor (ikisi de idam edilecekse adı rastgele seçiyor) ve "B idam edilecek" diyor. A\'nın affedilme olasılığı kaçtır?', '1/3', ['1/2', '2/3', '5/12'], 'Gardiyan A\'ya her durumda B ya da C\'den birini söyleyebilir; bu bilgi A\'nın olasılığını değiştirmez. C\'nin olasılığı ise 2/3\'e çıkar.'),
  ('Monty Hall probleminin geniş kamuoyunda tartışılmasına yol açan, Marilyn vos Savant\'ın 1990\'da yazdığı yanıt hangi yayın organında çıkmıştır?', 'Parade dergisi', ['The New York Times gazetesi', 'Scientific American dergisi', 'Time dergisi'], 'vos Savant, Parade dergisindeki "Ask Marilyn" köşesinde değiştirmenin avantajlı olduğunu yazmış ve binlerce itiraz mektubu almıştı.'),
  ('Üç mahkum probleminde gardiyanın "B idam edilecek" demesinden sonra C\'nin affedilme olasılığı kaçtır? (Gardiyan, A affedilecekse B ile C arasında rastgele seçim yapıyor.)', '2/3', ['1/2', '1/3', '5/12'], 'A\'nın olasılığı 1/3\'te kalır, B elenir; kalan olasılık C\'ye geçer: 1 − 1/3 = 2/3.'),
  ('Kırmızı, mavi ve yeşil üç zar atılıyor. Kırmızının maviden, mavinin de yeşilden kesinlikle küçük gelme olasılığı kaçtır?', '5/54', ['5/108', '5/18', '1/27'], 'Üç farklı değer C(6, 3) = 20 biçimde seçilir ve her seçimin tek bir artan sırası vardır: 20/216 = 5/54.'),
  ('İki zar atılıyor. Üst yüzlerin toplamının çarpımından büyük olma olasılığı kaçtır?', '11/36', ['1/3', '25/36', '13/36'], 'a + b > ab eşitsizliği yalnız zarlardan biri 1 olduğunda sağlanır; böyle 11 sıralı sonuç vardır. (2, 2) için toplam ile çarpım eşittir.'),
  ('Bir zar atılıyor ve üst yüzde kaç gelirse o kadar hilesiz para atılıyor. Paralardan hiçbirinin yazı gelmeme olasılığı kaçtır?', '21/128', ['1/64', '11/128', '63/128'], 'Toplam olasılıkla (1/6)(1/2 + 1/4 + … + 1/64) = (1/6)(63/64) = 21/128 bulunur.'),
  ('Hilesiz bir zar 6 gelene kadar atılıyor. İlk 6\'dan önce hiç 1 gelmemiş olma olasılığı kaçtır?', '1/2', ['5/6', '11/36', '1/3'], 'Yalnız 1 ve 6 sonuçları önemlidir ve ikisi eşit olasılıklıdır; hangisinin önce geleceği simetri gereği yarı yarıyadır.'),
  ('İki zar tekrar tekrar atılıyor. Toplamın 8 olmasının, toplamın 7 olmasından önce gerçekleşme olasılığı kaçtır?', '5/11', ['5/36', '25/36', '6/11'], 'Her atışta P(8) = 5/36, P(7) = 6/36\'dır. Diğer sonuçlar yok sayılırsa 8\'in önce gelme olasılığı 5 / (5 + 6) = 5/11\'dir.'),
  ('Üç zar atılıyor. Zarlardan tam olarak ikisinin aynı sayıyı gösterme olasılığı kaçtır?', '5/12', ['25/72', '5/9', '5/18'], 'Üçü farklı 120, üçü aynı 6 sonuç vardır; kalan 216 − 126 = 90 sonuçta tam iki zar aynıdır: 90/216 = 5/12.'),
  ('İki zar atılıyor. Zarların gösterdiği sayılardan birinin diğerini tam bölme (eşitlik dâhil) olasılığı kaçtır?', '11/18', ['13/18', '7/18', '2/3'], 'Sıralı çiftleri saymak gerekir: 1 her sayıyı böler, 2 ile 4 ve 6, 3 ile 6 gibi ilişkiler dâhil 22 sonuç vardır; 22/36 = 11/18.'),
  ('Hilesiz bir para beş kez atılıyor. Sonuç dizisinde art arda en az üç yazı bulunma olasılığı kaçtır?', '1/4', ['1/8', '3/16', '5/16'], 'YYY içeren diziler sayıldığında 32 diziden 8\'i koşulu sağlar: 8/32 = 1/4.'),
  ('Hilesiz bir para, YY ya da TY dizilerinden biri ardışık iki atışta görülene kadar atılıyor. YY dizisinin TY\'den önce görülme olasılığı kaçtır?', '1/4', ['1/2', '1/3', '3/8'], 'İlk iki atış YY değilse dizide bir T görülmüştür ve sonraki ilk Y\'den önce mutlaka T gelir; bu durumda TY önce oluşur. YY ancak ilk iki atış YY ise kazanır: 1/4.'),
  ('Hilesiz bir para n ≥ 1 kez atılıyor. Toplam yazı sayısının çift (sıfır dâhil) olma olasılığı için hangisi doğrudur?', 'n ne olursa olsun 1/2\'dir', ['n büyüdükçe 1\'e yaklaşır', 'Yalnız n çiftse 1/2\'dir', 'n büyüdükçe 0\'a yaklaşır'], 'Son atış, önceki atışların paritesini eşit olasılıkla korur ya da değiştirir; bu yüzden çift yazı olasılığı her n için 1/2\'dir.'),
  ('Ayşe 3, Burak 2 hilesiz para atıyor. Ayşe\'nin yazı sayısının Burak\'ınkinden kesinlikle fazla olma olasılığı kaçtır?', '1/2', ['2/3', '3/8', '11/32'], 'Ayşe\'nin parası Burak\'ınkinden bir fazla olduğundan ya yazıları ya da turaları Burak\'ınkinden fazla olur ve bu ikisi aynı anda gerçekleşemez. Yazı ile tura simetrik olduğundan iki durum eşit olasılıklıdır: 1/2.'),
  ('Hilesiz bir parayla ardışık iki yazı (YY) görülene kadar beklenen atış sayısı 6, YT dizisi için ise 4\'tür. Bu farkın nedeni nedir?', 'YY başarısız olunca baştan başlanır, YT\'de Y kazanımı korunur', ['YY dizisinin olasılığı YT\'ninkinden küçüktür', 'Para YY dizisinde hilelidir', 'YT dizisi iki farklı sonuç içerdiği için iki kat sık görülür'], 'İki dizinin her belirli konumda görülme olasılığı 1/4\'tür. YY\'de Y\'den sonra T gelince ilerleme kaybolur; YT\'de Y\'den sonra Y gelince yine bir Y elde tutulur.'),
  ('52\'lik desteden rastgele 4 kart alınıyor. Dört kartın dört farklı takımdan (maça, kupa, karo, sinek) olma olasılığı yaklaşık kaçtır?', '0,105', ['0,25', '0,0625', '0,0094'], 'Uygun el sayısı 13⁴ = 28561, toplam el C(52, 4) = 270725\'tir; oran yaklaşık 0,105\'tir.'),
  ('Poker\'de "full" eli, aynı değerden üç kart ile başka bir değerden iki karttan oluşur. 52 kartlık destede kaç farklı full eli vardır?', '3744', ['1872', '624', '7488'], 'Üçlü için 13 × C(4, 3) = 52, ikili için 12 × C(4, 2) = 72 seçim vardır: 52 × 72 = 3744.'),
  ('Briçte 52 karttan 13 kartlık bir el dağıtılıyor. Elde hiç as bulunmama olasılığı yaklaşık kaçtır?', '0,30', ['0,25', '0,0256', '0,4'], 'Olasılık C(48, 13) / C(52, 13) ≈ 0,304\'tür.'),
  ('Yirmi bir (blackjack) oyununda ilk iki kartın bir as ile 10 değerli bir kart (10, vale, kız, papaz) olması gerekir. Tek bir 52\'lik desteden ilk iki kartın böyle olma olasılığı yaklaşık kaçtır?', '0,048', ['0,024', '0,077', '0,0059'], 'Sıralı iki durum vardır: 2 × (4/52)(16/51) = 128/2652 ≈ 0,048.'),
  ('Birinci torbada 3 kırmızı 2 mavi, ikinci torbada 2 kırmızı 2 mavi top vardır. Birinci torbadan rastgele iki top ikinci torbaya aktarılıyor, ardından ikinci torbadan bir top çekiliyor. Çekilen topun kırmızı olma olasılığı kaçtır?', '8/15', ['1/2', '3/5', '17/30'], 'Aktarılan kırmızı sayısının beklenen değeri 2 × 3/5 = 1,2\'dir. İkinci torbada 6 top olduğundan olasılık (2 + 1,2)/6 = 8/15 olur.'),
  ('Bir torbada 4 kırmızı ve 6 mavi top var. Toplar yerine konmadan tek tek çekiliyor. Üçüncü topun kırmızı, beşincinin mavi olma olasılığı kaçtır?', '4/15', ['6/25', '2/5', '12/25'], 'Belirli iki sıranın renk dağılımı ilk iki çekilişinkiyle aynıdır: (4/10)(6/9) = 24/90 = 4/15.'),
  ('Bir torbada 3 kırmızı ve 2 mavi top var. Yerine koymadan iki top çekiliyor ve ikinci topun kırmızı olduğu biliniyor. Birinci topun da kırmızı olma olasılığı kaçtır?', '1/2', ['3/5', '2/5', '3/10'], 'Simetriden ötürü, ikinci top kırmızı iken birincinin rengi, birinci kırmızı iken ikincinin rengiyle aynı dağılıma sahiptir: 2/4 = 1/2.'),
  ('Lewis Carroll\'un bir bilmecesinde bir torbada eşit olasılıkla ya beyaz ya siyah tek bir top vardır. Torbaya bir beyaz top ekleniyor, karıştırılıp bir top çekiliyor ve beyaz çıkıyor. Torbada kalan topun beyaz olma olasılığı kaçtır?', '2/3', ['1/2', '5/12', '1/3'], 'Başlangıç beyazsa beyaz çekme olasılığı 1, siyahsa 1/2\'dir. Sonsal (1/2)(1) / [(1/2)(1) + (1/2)(1/2)] = 2/3 olur.'),
  ('Bir dolapta 5 çift ayakkabı vardır. Karanlıkta rastgele 4 tek ayakkabı alınıyor. Alınanlar arasında hiç eş ayakkabı bulunmama olasılığı kaçtır?', '8/21', ['1/2', '5/21', '13/21'], 'Dört farklı çift C(5, 4) = 5 biçimde seçilir, her çiftten sağ ya da sol alınır: 5 × 2⁴ = 80. C(10, 4) = 210 olduğundan olasılık 80/210 = 8/21\'dir.'),
  ('49 sayıdan 6\'sının çekildiği bir piyangoda bir kupon 6 sayı içeriyor. Kuponun çekilen sayılardan tam olarak 3\'ünü bilme olasılığı yaklaşık kaçtır?', '0,018', ['0,05', '0,0009', '0,0613'], 'Olasılık C(6, 3) × C(43, 3) / C(49, 6) = 20 × 12341 / 13983816 ≈ 0,0177\'dir.'),
  ('49 sayıdan 6\'sının çekildiği bir piyangoda 6 sayılık bir kuponun çekilen sayılardan hiçbirini bilmeme olasılığı yaklaşık kaçtır?', '0,44', ['0,88', '0,12', '0,265'], 'Kupondaki 6 sayının hepsi çekilmeyen 43 sayı arasından olmalıdır: C(43, 6)/C(49, 6) ≈ 0,436.'),
  ('KAYAK sözcüğünün harfleri rastgele diziliyor. Elde edilen dizilimin baştan ve sondan aynı okunan (palindrom) bir sözcük olma olasılığı kaçtır?', '1/15', ['1/30', '1/120', '2/15'], 'Farklı dizilim sayısı 5!/(2! 2!) = 30\'dur. Palindromda ortada Y bulunmalı, ilk iki harf K ve A\'nın 2 sıralanışından biri olmalıdır: 2/30.'),
  ('1, 2, 3, 4 ve 5 rakamları birer kez kullanılarak rastgele beş basamaklı bir sayı oluşturuluyor. Sayının 4\'e bölünebilme olasılığı kaçtır?', '1/5', ['1/4', '2/5', '3/20'], '4\'e bölünebilmek için son iki basamak 12, 24, 32 ya da 52 olmalıdır. Son iki basamak için 20 sıralı seçenek olduğundan olasılık 4/20 = 1/5\'tir.'),
  ('Dört mektup dört zarfa rastgele konuyor. Tam olarak bir mektubun kendi zarfına girme olasılığı kaçtır?', '1/3', ['1/4', '3/8', '1/24'], 'Doğru yerleşen mektup 4 biçimde seçilir; kalan üçünün hiçbirinin doğru yerleşmemesi 2 biçimde olur: 8/24 = 1/3.'),
  ('n mektup n zarfa rastgele konduğunda kendi zarfına giden mektupların beklenen sayısı kaçtır?', 'n\'den bağımsız olarak 1\'dir', ['n/2\'dir', '1/n\'dir ve n büyüdükçe küçülür', 'n büyüdükçe sıfıra yaklaşır'], 'Her mektup 1/n olasılıkla doğru zarfa gider; n mektup için beklenen değer n × (1/n) = 1\'dir.'),
  ('Doğum günü probleminde n kişilik grupta hiç ortak doğum günü olmama olasılığı için sık kullanılan yaklaşık ifade hangisidir?', 'exp(−n(n − 1)/730)', ['1 − n/365', 'exp(−n/365)', '1 − n(n − 1)(n − 2)/365²'], 'İkili sayısı n(n − 1)/2\'dir ve her ikili 1/365 olasılıkla eşleşir; bu yaklaşık olarak e üzeri −n(n − 1)/(2 × 365) verir.'),
  ('[0, 1] aralığından bağımsız ve düzgün iki sayı seçiliyor. Sayıların çarpımının 1/2\'den küçük olma olasılığı yaklaşık kaçtır?', '0,85', ['0,50', '0,75', '0,693'], 'Bölgenin alanı 1/2 + ∫ (1/(2x)) dx (x: 1/2\'den 1\'e) = 1/2 + (1/2) ln 2 ≈ 0,847\'dir.'),
  ('Bir çubuk, üzerinde bağımsız ve düzgün olarak seçilen iki noktadan kırılarak üç parçaya ayrılıyor. Üç parçanın bir üçgen oluşturabilme olasılığı kaçtır?', '1/4', ['3/16', '1/3', '3/8'], 'Üçgen için her parça çubuğun yarısından kısa olmalıdır; birim karede bu koşulu sağlayan bölgenin alanı 1/4\'tür.'),
  ('Bir analog saate rastgele bir anda bakılıyor. Akrep ile yelkovan arasındaki küçük açının 30°\'den az olma olasılığı kaçtır?', '1/6', ['1/12', '1/4', '1/3'], 'Yelkovan ile akrep arasındaki göreli açı uzun dönemde 0°–360° arasında düzgün dağılır. Küçük açının 30°\'den az olması için göreli açı 0–30° ya da 330–360° arasında olmalıdır: 60/360.'),
  ('Ece ile Mert sırayla basket atışı yapıyor; ilk sayı yapan kazanıyor. Ece\'nin isabet olasılığı 0,4, Mert\'inki 0,5\'tir ve ilk atışı Ece yapıyor. Ece\'nin kazanma olasılığı kaçtır?', '4/7', ['2/5', '1/2', '9/14'], 'Bir turda kimsenin isabet ettirememe olasılığı 0,6 × 0,5 = 0,3\'tür. Ece\'nin kazanma olasılığı 0,4 / (1 − 0,3) = 4/7 olur.'),
  ('Üç arkadaş sırayla hilesiz bir para atıyor ve ilk yazı atan kazanıyor. Sırada üçüncü olan arkadaşın kazanma olasılığı kaçtır?', '1/7', ['1/3', '1/8', '3/14'], 'Bir tam turun yazısız geçme olasılığı 1/8\'dir. Üçüncü oyuncu için (1/8) / (1 − 1/8) = 1/7 bulunur; ilk iki oyuncu için değerler 4/7 ve 2/7\'dir.'),
  ('İlk üç galibiyete ulaşanın kazandığı beş maçlık bir seride iki eşit güçteki takımdan A ilk maçı kazanmıştır. A\'nın seriyi kazanma olasılığı kaçtır?', '11/16', ['1/2', '13/16', '21/32'], 'Seri, kalan dört maçın hepsi oynanıyormuş gibi düşünülebilir; A\'nın bu dört maçtan en az ikisini kazanması gerekir: 11/16.'),
  ('İlk dört galibiyete ulaşanın kazandığı yedi maçlık bir seride iki takım eşit güçtedir. Serinin yedinci maça kalma olasılığı kaçtır?', '5/16', ['1/8', '1/4', '35/128'], 'İlk altı maç 3-3 bitmelidir: C(6, 3)/2⁶ = 20/64 = 5/16.'),
  ('Bir kumarbaz 3 lirayla başlıyor ve her turda eşit olasılıkla 1 lira kazanıp kaybediyor. 10 liraya ulaşınca ya da parası bitince duruyor. Kumarbazın 10 liraya ulaşma olasılığı kaçtır?', '3/10', ['3/100', '7/10', '1/3'], 'Adil oyunda servet bir martingaldir; k liradan başlayıp N\'ye ulaşma olasılığı k/N\'dir: 3/10.'),
  ('Adil bir oyunda sınırlı parası olan bir oyuncu, sınırsız kaynağa sahip bir kumarhaneye karşı her turda 1 lira yatırarak oynamayı sürdürüyor. Oyuncunun eninde sonunda iflas etme olasılığı kaçtır?', '1', ['1/2', '0', 'Başlangıç servetine bağlıdır'], 'Hedef N sonsuza giderken ulaşma olasılığı k/N sıfıra iner; iflas olasılığı 1\'e yaklaşır.'),
  ('Bir oyuncu her turda 2/3 olasılıkla 1 lira kazanıyor, 1/3 olasılıkla 1 lira kaybediyor. 1 lirayla başlayan oyuncu 3 liraya ulaşınca ya da parası bitince duruyor. 3 liraya ulaşma olasılığı kaçtır?', '4/7', ['2/3', '1/3', '8/27'], 'r = q/p = 1/2 olmak üzere olasılık (1 − r¹)/(1 − r³) = (1/2)/(7/8) = 4/7 bulunur.'),
  ('İki heterozigot (Aa) bireyin çaprazlanmasından baskın fenotipli bir yavru doğuyor. Bu yavrunun heterozigot (Aa) olma olasılığı kaçtır?', '2/3', ['1/2', '1/4', '5/12'], 'Baskın fenotipliler AA (1/4) ve Aa (1/2) olanlardır. Koşullu olasılık (1/2)/(3/4) = 2/3 bulunur.'),
  ('Bir arızanın herhangi bir günde yaşanma olasılığı 1/1000\'dir ve günler bağımsızdır. 365 günlük bir yılda en az bir arıza yaşanma olasılığı yaklaşık kaçtır?', '0,31', ['0,365', '0,001', '0,0365'], 'Hiç arıza olmama olasılığı 0,999³⁶⁵ ≈ 0,694\'tür; tümleyeni yaklaşık 0,306\'dır.'),
  ('Olasılığı milyonda bir olan bir olay için bir milyon bağımsız deneme yapılıyor. Olayın en az bir kez gerçekleşme olasılığı yaklaşık kaçtır?', '0,63', ['1', '0,50', '0,368'], '(1 − 1/n)ⁿ ≈ 1/e ≈ 0,368 olduğundan en az bir kez gerçekleşme olasılığı yaklaşık 1 − 0,368 = 0,632\'dir.'),
  ('Her denemede başarı olasılığı 0,1 olan bağımsız denemelerde en az bir başarı olasılığının 1/2\'yi ilk kez geçmesi için en az kaç deneme gerekir?', '7', ['5', '10', '6'], '1 − 0,9⁶ ≈ 0,469 ve 1 − 0,9⁷ ≈ 0,522\'dir; eşik ilk kez 7 denemede aşılır.'),
  ('Her denemede olasılığı 0,01 olan bir olayı en az bir kez görme olasılığının 0,95 ya da daha fazla olması için en az kaç bağımsız deneme gerekir?', '299', ['95', '100', '1000'], '0,99ⁿ ≤ 0,05 olmalıdır. 0,99²⁹⁸ ≈ 0,0500 (biraz büyük), 0,99²⁹⁹ ≈ 0,0495\'tir; bu yüzden 299 deneme gerekir.'),
  ('Bir uçağın kontrol sistemi bağımsız üç bilgisayardan en az ikisi aynı sonucu verdiğinde doğru çalışıyor (çoğunluk oylaması). Her bilgisayarın doğru çalışma olasılığı 0,9 ise sistemin doğru çalışma olasılığı kaçtır?', '0,972', ['0,729', '0,9963', '0,9'], 'Üçü de çalışır: 0,729; tam ikisi çalışır: 3 × 0,81 × 0,1 = 0,243. Toplam 0,972\'dir.'),
  ('Her biri bağımsız olarak 0,6 olasılıkla çalışan özdeş pompalar paralel bağlanacaktır. Sistemin çalışma olasılığının en az 0,99 olması için en az kaç pompa gerekir?', '6', ['5', '3', '10'], 'Hepsinin arızalanma olasılığı 0,4ⁿ\'dir. 0,4⁵ ≈ 0,0102 > 0,01 iken 0,4⁶ ≈ 0,0041 < 0,01 olduğundan 6 pompa gerekir.'),
  ('Çalışma olasılıkları 0,9 olan A ve 0,8 olan B parçası bağımsız olup seri bağlıdır. Sistemin çalışmadığı görülüyor. Arızanın A\'da olma olasılığı (B\'nin durumu ne olursa olsun) yaklaşık kaçtır?', '0,36', ['0,10', '0,50', '0,7143'], 'Sistemin arızalanma olasılığı 1 − 0,72 = 0,28\'dir. A\'nın arızalı olma olasılığı 0,1 olduğundan P(A arızalı | sistem arızalı) = 0,1 / 0,28 ≈ 0,36 bulunur.'),
  ('Sürücülerin %2\'sinin alkollü olduğu bir bölgede kazaya karışan sürücülerin %40\'ı alkollüdür. Bu verilere göre alkollü bir sürücünün kazaya karışma olasılığı, alkolsüz bir sürücününkinin yaklaşık kaç katıdır?', '33', ['20', '16,3', '2'], 'P(kaza | alkollü) ∝ 0,40/0,02 = 20 ve P(kaza | alkolsüz) ∝ 0,60/0,98 ≈ 0,612\'dir; oran yaklaşık 20/0,612 ≈ 33\'tür.'),
  ('Bir raporda P(B) = 0,5, P(A|B) = 0,6 ve P(A) = 0,2 olarak verilmiştir. Bu değerler için hangisi doğrudur?', 'Tutarsızdır; P(A ∩ B) = 0,3 olur ve P(A)\'yı aşar', ['Tutarlıdır; A ile B pozitif yönde ilişkili olaylardır', 'Tutarlıdır; P(A|B\') = 0 olur', 'Tutarsızdır, çünkü P(A|B) P(B)\'den büyük olamaz'], 'P(A ∩ B) = 0,6 × 0,5 = 0,3\'tür; oysa bir kesişim P(A) = 0,2 değerini aşamaz.'),
  ('Beş seçenekli bir testte öğrenci bir sorunun yanıtını 0,6 olasılıkla biliyor; bilmiyorsa rastgele işaretliyor. Öğrencinin bu soruyu doğru yanıtladığı görülüyor. Yanıtı gerçekten biliyor olma olasılığı yaklaşık kaçtır?', '0,88', ['0,60', '0,68', '0,925'], 'P(doğru) = 0,6 + 0,4 × 0,2 = 0,68\'dir. P(biliyor | doğru) = 0,6 / 0,68 ≈ 0,882 bulunur.'),
  ('Bir yalan makinesi yalan söyleyenlerin %90\'ını, doğruyu söyleyenlerin ise %10\'unu "yalan" olarak işaretliyor. Sorgulananların %5\'i yalan söylüyorsa, makinenin "yalan" dediği birinin gerçekten yalan söylüyor olma olasılığı yaklaşık kaçtır?', '0,32', ['0,90', '0,05', '0,4737'], 'P(yalan ∩ işaret) = 0,045; P(işaret) = 0,045 + 0,095 = 0,14\'tür. 0,045 / 0,14 ≈ 0,32 bulunur.'),
  ('Galileo\'ya sorulan ünlü bir soruda, üç zarla toplam 9 ve toplam 10\'un ikisi de altı farklı biçimde (sırasız) yazılabildiği hâlde neden toplam 10\'un daha sık geldiği merak ediliyordu. Doğru açıklama hangisidir?', 'Sıralı sonuçlar sayılınca 10 için 27, 9 için 25 durum vardır', ['Toplam 10 için yazılış sayısı aslında yedidir', 'O dönemin zarları hileli üretildiği için 10 daha sık geliyordu', 'Toplam 9 yalnız çift sayılarla elde edilebilir'], 'Sırasız yazılışlar eşit olasılıklı değildir; 216 sıralı sonuç içinde toplam 10 için 27, toplam 9 için 25 sonuç vardır.'),
  ('Samuel Pepys\'in 1693\'te Isaac Newton\'a sorduğu soruda üç olay karşılaştırılıyordu: 6 zarda en az bir 6, 12 zarda en az iki 6 ve 18 zarda en az üç 6. Hangisinin olasılığı en büyüktür?', 'Altı zarla en az bir altı elde etmek', ['On iki zarla en az iki altı elde etmek', 'On sekiz zarla en az üç altı elde etmek', 'Üç olayın olasılığı birbirine eşittir'], 'Olasılıklar sırasıyla yaklaşık 0,665, 0,619 ve 0,597\'dir; beklenen 6 sayısı orantılı olsa da olasılıklar eşit değildir.'),
  ('Laplace\'ın ardıllık kuralına göre n bağımsız denemede s başarı gözlendiğinde bir sonraki denemenin başarılı olma olasılığı hangi ifadeyle tahmin edilir?', '(s + 1) / (n + 2)', ['s / n', '(s + 1) / (n + 1)', '(s + 1) / (n + s + 2)'], 'Başarı olasılığı için düzgün önsel alındığında sonraki denemenin başarı olasılığı (s + 1)/(n + 2) çıkar; hiç gözlem yokken bu 1/2\'dir.'),
  ('"Olasılık yoktur" (nesnel bir olasılık bulunmadığı, olasılığın kişisel inanç derecesi olduğu) görüşüyle tanınan İtalyan olasılık kuramcısı kimdir?', 'Bruno de Finetti', ['Gerolamo Cardano', 'Vito Volterra', 'Francesco Paolo Cantelli'], 'De Finetti, öznel (kişisel) olasılık yorumunun öncülerindendir ve "Probability does not exist" ifadesiyle bilinir.'),
  ('Öznel olasılık kuramında "Hollanda kitabı" (Dutch book) argümanı neyi gösterir?', 'Olasılık kurallarına uymayan inançlarla bahse girenin kesin zarara uğratılabileceğini', ['Adil bir zarın her yüzünün eşit olasılıklı olduğunu', 'Büyük sayılar yasasının yalnızca öznel olasılık yorumunda geçerli olduğunu ve başka yorumlarda geçersiz kaldığını', 'Hollanda\'da kumarın olasılık kuramını doğurduğunu'], 'Tutarsız olasılık atayan biri, her sonuçta para kaybedeceği bir bahis dizisini adil görür; bu, olasılık aksiyomlarına uymanın gerekçesi olarak kullanılır.'),
  ('1494\'te yayımlanan "Summa" adlı eserinde yarıda kalan bir oyunun ödülünün o ana kadar kazanılan puanlarla orantılı bölüşülmesini öneren, sonradan hatalı olduğu anlaşılan çözümün sahibi kimdir?', 'Luca Pacioli', ['Gerolamo Cardano', 'Niccolò Tartaglia', 'Christiaan Huygens'], 'Pacioli\'nin orantılı bölüşümü, kalan oyunların olasılıklarını hesaba katmadığı için yanlıştır; doğru çözümü Pascal ve Fermat 1654\'te buldu.'),
  ('Penney oyununda hilesiz bir parayla birinci oyuncu YYT dizisini seçiyor; ikinci oyuncu TYY\'yi seçiyor. Para, seçilen dizilerden biri art arda görülene kadar atılıyor. TYY\'nin önce görülme olasılığı kaçtır?', '3/4', ['1/2', '2/3', '11/16'], 'YYT ancak ilk iki atış YY ise kazanır (1/4); aksi hâlde YY\'den önce bir T görülmüş olur ve YY oluştuğu an TYY tamamlanır.'),
  ('Kutularda üç farklı oyuncaktan biri eşit olasılıkla bulunuyor. Dört kutu alan birinin üç oyuncağın hepsini elde etme olasılığı kaçtır?', '4/9', ['2/9', '2/3', '13/27'], 'Her oyuncağın en az bir kez geldiği dizi sayısı 3⁴ − 3 × 2⁴ + 3 × 1 = 81 − 48 + 3 = 36\'dır: 36/81 = 4/9.'),
  ('Kolmogorov\'un olasılığın aksiyomatik temelini kurduğu 1933 tarihli eserinin adı hangisidir?', 'Grundbegriffe der Wahrscheinlichkeitsrechnung', ['Ars Conjectandi', 'Wahrscheinlichkeit, Statistik und Wahrheit', 'Liber de Ludo Aleae'], 'Almanca yayımlanan eser "Olasılık Hesabının Temel Kavramları" anlamına gelir ve olasılığı ölçü kuramına dayandırır.'),
  ('100 koltuklu bir uçağa yolcular sırayla biniyor. İlk yolcu biletini kaybettiği için rastgele bir koltuğa oturuyor; sonraki her yolcu kendi koltuğu boşsa oraya, doluysa boş koltuklardan rastgele birine oturuyor. Son yolcunun kendi koltuğuna oturma olasılığı kaçtır?', '1/2', ['1/100', '99/100', '1/e'], 'Süreç ilk yolcunun ya da son yolcunun koltuğu dolduğunda belirlenir ve her aşamada bu iki koltuk eşit şansa sahiptir; son boş koltuk bunlardan biridir.'),
  ('Bir seçimde A adayı 3, B adayı 2 oy almıştır. Oylar rastgele sırayla tek tek sayılıyor. Sayım boyunca A\'nın her an B\'den kesinlikle önde olma olasılığı kaçtır?', '1/5', ['3/5', '2/5', '1/10'], 'Oy pusulası (ballot) teoremine göre olasılık (a − b)/(a + b) = (3 − 2)/5 = 1/5\'tir.'),
  ('İki zar atılıyor ve toplamın 8 olduğu biliniyor. Birinci zarın beklenen değeri kaçtır?', '4', ['3,5', '5', '4,5'], 'Koşulu sağlayan sonuçlarda birinci zar 2, 3, 4, 5, 6 değerlerini eşit olasılıkla alır; ortalama 4\'tür. Simetriden iki zarın beklenen değeri eşittir ve toplamları 8\'dir.'),
  ('Bir kentte nüfusun %90\'ı aşılıdır ve bir salgında hastalananların yarısı aşılıdır. Bu verilere göre aşılı bir kişinin hastalanma olasılığı, aşısız birininkinin yaklaşık kaçta biridir?', '1/9', ['1/2', '1', '1/90'], 'P(hasta | aşılı) ∝ 0,5/0,9, P(hasta | aşısız) ∝ 0,5/0,1\'dir. Oran (0,5/0,9)/(0,5/0,1) = 1/9 olur; hastaların yarısının aşılı olması aşının etkisiz olduğunu göstermez.'),
  ('Bir üretim hattında ürünlerin %5\'i kusurludur. Muayene kusurlu ürünlerin %95\'ini reddediyor, sağlam ürünlerin %2\'sini yanlışlıkla reddediyor. Muayeneden geçip kabul edilen bir ürünün kusurlu olma olasılığı yaklaşık kaçtır?', '0,0027', ['0,05', '0,0025', '0,0714'], 'Kabul edilen kusurlular 0,05 × 0,05 = 0,0025, kabul edilen sağlamlar 0,95 × 0,98 = 0,931\'dir. 0,0025 / 0,9335 ≈ 0,0027 bulunur.'),
  ('52\'lik desteden iki kart dağıtılıyor ve kartlardan en az birinin as olduğu söyleniyor. İki kartın da as olma olasılığı kaçtır?', '1/33', ['1/17', '1/221', '1/13'], 'P(iki as) = 6/1326, P(en az bir as) = 1 − 1128/1326 = 198/1326\'dır. Oran 6/198 = 1/33\'tür.'),
  ('Bir oyuncuya karılmış desteden iki kart veriliyor. Oyuncu kartlarına bakıp "Elimde maça ası var" diyor. Elindeki iki kartın ikisinin de as olması hangi olasılıkla doğrudur?', '1/17', ['1/33', '1/13', '1/221'], 'Maça ası belli olduğundan diğer kart kalan 51 karttan biridir ve bunların 3\'ü astır: 3/51 = 1/17. Belirli bir as bilgisi "en az bir as" bilgisinden farklı sonuç verir.'),
  ('Bir kentte günlerin %30\'u yağmurludur. Yağmurlu günlerde trafik sıkışıklığı olasılığı 0,8, kuru günlerde 0,3\'tür. Trafiğin sıkışık olmadığı bir günün yağmurlu olma olasılığı yaklaşık kaçtır?', '0,11', ['0,30', '0,06', '0,2182'], 'P(yağmur ∩ sıkışıklık yok) = 0,3 × 0,2 = 0,06; P(sıkışıklık yok) = 0,06 + 0,7 × 0,7 = 0,55\'tir. 0,06 / 0,55 ≈ 0,11.'),
  ('Farklı önsel olasılıklarla başlayan iki araştırmacı aynı hipotezi koşullu bağımsız ve bilgilendirici kanıtlarla güncellemeyi sürdürüyor (ikisinin de önseli 0 ya da 1 değildir). Kanıt sayısı arttıkça sonsalları için genellikle ne beklenir?', 'Birbirine yaklaşır', ['Aralarındaki fark sabit kalır', 'Birbirinden giderek uzaklaşır', 'İkisi de 1/2\'ye yaklaşır'], 'Kanıt biriktikçe olabilirlik önsele baskın gelir; önseller sıfır ya da bir olmadıkça sonsallar aynı değere yakınsar.'),
  ('Kolmogorov\'un yaklaşımında bir olasılık uzayı hangi üç bileşenden oluşur?', 'Örnek uzay, olaylar ailesi ve olasılık ölçüsü', ['Örnek uzay, rastgele değişken ve beklenen değer', 'Olay, tümleyen ve kesişim', 'Deney, gözlem ve sıklık'], 'Olasılık uzayı (Ω, F, P) üçlüsüyle gösterilir: Ω örnek uzay, F olaylar ailesi (σ-cebir), P olasılık ölçüsüdür.'),
  ('P(A) = 0,6, P(B|A) = 0,5 ve P(B|A\') = 0,25 veriliyor. B\'nin gerçekleşmediği bilindiğinde A\'nın olasılığı kaçtır?', '0,5', ['0,6', '0,75', '0,3'], 'P(B) = 0,3 + 0,1 = 0,4 ve P(B\') = 0,6\'dır. P(A ∩ B\') = 0,6 × 0,5 = 0,3 olduğundan P(A|B\') = 0,3 / 0,6 = 0,5 bulunur.'),
  ('P(A|B) = 0,7 ve P(A|B\') = 0,3 olarak verilmiştir (0 < P(B) < 1). Aşağıdakilerden hangisi P(A)\'nın değeri olamaz?', '0,8', ['0,5', '0,35', '0,65'], 'Toplam olasılık kuralına göre P(A) = 0,7P(B) + 0,3P(B\') iki koşullu olasılığın ağırlıklı ortalamasıdır ve 0,3 ile 0,7 arasında kalmak zorundadır.'),
  ('Bir okulda öğrencilerin yarısı spor yapıyor. Servis kullananların %80\'i, servis kullanmayanların %30\'u spor yapıyor. Öğrencilerin hangi oranı servis kullanıyor?', '0,4', ['0,5', '0,6', '0,625'], 'S servis kullanma olmak üzere 0,5 = 0,8P(S) + 0,3(1 − P(S)) eşitliğinden 0,2 = 0,5P(S) ve P(S) = 0,4 bulunur.'),
  ('Dört kız ve dört erkek öğrenci rastgele düz bir sıraya diziliyor. Sıranın kız ve erkekler dönüşümlü (bir kız, bir erkek) olacak biçimde oluşma olasılığı kaçtır?', '1/35', ['1/70', '1/350', '2/35'], 'Uygun dizilişler 2 × 4! × 4! = 1152, tüm dizilişler 8! = 40320\'dir; oran 1/35\'tir.'),
  ('Üç basamaklı sayılardan biri rastgele seçiliyor. Rakamlarının soldan sağa kesin artan (örneğin 147) olma olasılığı kaçtır?', '7/75', ['1/6', '84/1000', '1/9'], 'Kesin artan rakamlar 0 içeremez ve 1–9 arasından C(9, 3) = 84 biçimde seçilir: 84/900 = 7/75.'),
  ('1\'den 100\'e kadar olan sayılardan farklı iki tanesi rastgele seçiliyor. Çarpımlarının çift olma olasılığı kaçtır?', '149/198', ['1225/4950', '1/2', '3/4'], 'Çarpımın tek olması için ikisi de tek olmalıdır: C(50, 2)/C(100, 2) = 1225/4950 = 49/198. Tümleyeni 149/198\'dir.'),
  ('Düzgün bir altıgenin köşelerinden üç tanesi rastgele seçiliyor. Seçilen köşelerin bir eşkenar üçgen oluşturma olasılığı kaçtır?', '1/10', ['1/20', '2/120', '3/20'], 'Altıgenin köşeleriyle yalnız iki eşkenar üçgen (birer atlayarak) kurulabilir; C(6, 3) = 20 seçimden 2\'si uygundur.'),
  ('Bir torbada üç zar var: biri hilesiz, biri bütün yüzlerinde 6 yazan, biri de üç yüzünde 6 yazan bir zardır. Rastgele seçilen zar atılıyor ve 6 geliyor. Bütün yüzleri 6 olan zarın seçilmiş olma olasılığı kaçtır?', '3/5', ['1/3', '1/2', '6/11'], 'Olabilirlikler 1/6, 1 ve 1/2\'dir; eşit önsellerle sonsal 1 / (1/6 + 1 + 1/2) = 3/5 bulunur.'),
  ('Bir torbada hilesiz bir zar, bütün yüzleri 6 olan bir zar ve üç yüzü 6 olan bir zar bulunuyor. Rastgele seçilen bir zar iki kez atılıyor ve iki atışta da 6 geliyor. Bütün yüzleri 6 olan zarın seçilmiş olma olasılığı kaçtır?', '18/23', ['3/5', '26/27', '36/49'], 'Olabilirlikler 1/36, 1 ve 1/4\'tür. Sonsal 1 / (1/36 + 1 + 9/36) = 36/46 = 18/23 olur; ikinci 6 hileli zar lehine kanıtı güçlendirir.'),
  ('Anahtarların 0,6 olasılıkla evde, 0,3 olasılıkla işyerinde, 0,1 olasılıkla arabada olduğu düşünülüyor. Ev aranıyor; anahtar evdeyse arama onu 0,8 olasılıkla buluyor. Evde bulunamadığına göre anahtarın evde olma olasılığı kaçtır?', '3/13', ['0,1154', '0,12', '6/13'], 'P(evde ∩ bulunamadı) = 0,6 × 0,2 = 0,12; P(bulunamadı) = 0,12 + 0,4 = 0,52\'dir. 0,12 / 0,52 = 3/13 bulunur.'),
  ('Anahtarların 0,6 olasılıkla evde, 0,3 olasılıkla işyerinde, 0,1 olasılıkla arabada olduğu düşünülüyor. Evdeki arama, anahtar oradaysa 0,8 olasılıkla başarılı oluyor ve anahtar bulunamıyor. Anahtarın işyerinde olma olasılığı kaçtır?', '15/26', ['17/26', '3/13', '3/4'], 'Evde bulunamama olasılığı 0,52\'dir. İşyerindeyse ev araması kesinlikle başarısız olur: 0,3 / 0,52 = 15/26.'),
  ('Yaygınlığı %10 olan bir hastalık için duyarlılığı 0,9, özgüllüğü 0,8 olan bir test iki kez uygulanıyor; sonuçlar kişinin durumu bilindiğinde bağımsızdır. Birinci test pozitif, ikinci test negatif çıkıyor. Kişinin hasta olma olasılığı yaklaşık kaçtır?', '0,06', ['0,153', '0,33', '0,5'], 'P(+, − | hasta) = 0,9 × 0,1 = 0,09; P(+, − | sağlıklı) = 0,2 × 0,8 = 0,16\'dır. 0,009 / (0,009 + 0,144) ≈ 0,059 bulunur.'),
  ('Gelen iletilerin %40\'ı istenmeyen iletidir. "kazan" sözcüğü istenmeyen iletilerin %50\'sinde, normal iletilerin %5\'inde; "ücretsiz" sözcüğü istenmeyenlerin %60\'ında, normallerin %10\'unda geçiyor. Sözcükler her sınıfta bağımsız varsayılırsa iki sözcüğü de içeren bir iletinin istenmeyen olma olasılığı yaklaşık kaçtır?', '0,98', ['0,40', '0,30', '0,8571'], 'İstenmeyen için 0,4 × 0,5 × 0,6 = 0,12; normal için 0,6 × 0,05 × 0,1 = 0,003\'tür. 0,12 / 0,123 ≈ 0,976 bulunur.'),
  ('Bir oyuncunun 6 gelme olasılığı 1/2 olan hileli bir zar kullanma olasılığı 0,1\'dir; aksi hâlde hilesiz zar kullanıyor. Oyuncu üç kez zar atıyor ve üçünde de 6 geliyor. Hileli zar kullanıyor olma olasılığı kaçtır?', '0,75', ['0,10', '0,5', '0,9643'], 'Hileli için 0,1 × 1/8 = 0,0125, hilesiz için 0,9 × 1/216 ≈ 0,00417\'dir. 0,0125 / 0,01667 = 0,75 bulunur.'),
  ('100 öğrencinin 50\'si İngilizce, 30\'u Almanca, 20\'si Fransızca biliyor. İngilizce-Almanca bilen 10, İngilizce-Fransızca bilen 8, Almanca-Fransızca bilen 5 ve üç dili de bilen 3 öğrenci var. Rastgele bir öğrencinin bu dillerden yalnız birini bilme olasılığı kaçtır?', '0,63', ['0,80', '0,35', '0,575'], 'Yalnız İngilizce 35, yalnız Almanca 18, yalnız Fransızca 10 öğrencidir; toplam 63 öğrenci yalnız bir dil bilir.'),
  ('1\'den 1000\'e kadar olan tam sayılardan biri rastgele seçiliyor. Sayının tam kare ya da tam küp olma olasılığı kaçtır?', '0,038', ['0,041', '0,031', '0,0350'], 'Tam kareler 31, tam küpler 10 tanedir; hem kare hem küp olan altıncı kuvvetler 1, 64 ve 729\'dur: 31 + 10 − 3 = 38.'),
  ('Tavlada bir oyuncu, 6 hane uzaktaki rakip taşını tek atışta vurmak istiyor; aradaki haneler boştur ve çift zar dört hamle sağlar. Bu atışta vurma olasılığı kaçtır?', '17/36', ['11/36', '19/36', '5/12'], 'Bir zarı 6 olan 11 sonuç, toplamı 6 olan (1,5), (5,1), (2,4), (4,2), (3,3) ve dört kez 2 ilerleten (2,2) eklenince 17 sonuç olur.'),
  ('Bir basketbolcu ilk serbest atışı 0,7 olasılıkla sokuyor; ilki girerse ikinciyi 0,8, girmezse 0,6 olasılıkla sokuyor. İkinci atışın girdiği bilindiğine göre ilk atışın da girmiş olma olasılığı yaklaşık kaçtır?', '0,76', ['0,625', '0,80', '0,56'], 'P(ilk ∩ ikinci) = 0,56, P(ikinci) = 0,74\'tür. 0,56 / 0,74 ≈ 0,76 bulunur.'),
  ('Bir kentte taksilerin %15\'i mavi, %85\'i yeşildir. Renkleri %80 doğrulukla tanıyan ve birbirinden bağımsız iki tanık, kazaya karışan taksinin mavi olduğunu söylüyor. Taksinin gerçekten mavi olma olasılığı yaklaşık kaçtır?', '0,74', ['0,4138', '0,96', '0,64'], 'Önsel oran 15:85\'tir; her tanığın olabilirlik oranı 0,8/0,2 = 4\'tür. Sonsal oran 15 × 16 : 85 = 240 : 85, olasılık 240/325 ≈ 0,74\'tür.'),
  ('Sürücülerin %20\'sinin yüksek riskli (yıllık kaza olasılığı 0,3), %80\'inin düşük riskli (0,05) olduğu bir şirkette yıllar, sürücünün grubu bilindiğinde bağımsızdır. Bir yıl kaza yapan sürücünün ertesi yıl da kaza yapma olasılığı kaçtır?', '0,2', ['0,1', '0,3', '0,09'], 'P(iki yıl kaza) = 0,2 × 0,09 + 0,8 × 0,0025 = 0,02\'dir. 0,02 / 0,10 = 0,2 olur; kaza bilgisi yüksek risk olasılığını artırdığı için değer 0,1\'in üstündedir.'),
];
